#include <bits/stdc++.h>
using namespace std;

#define FOR(i, n) for (int i = 0; i < (int)(n); ++i)
#define push_back b
#define emplace_back e
#define first f
#define second s
typedef long long ll;
typedef vector<int> vi;
typedef pair<int, int> pii;
typedef long double ld;

const int MAX_SIZE = 21;
const ld TOLERANCE = 1e-6;

int count = 0, k_value, m_value;
ld prob[M_SIZE];
int idx[M_SIZE];
ld dp[1 << MAX_SIZE];
ld answer[M_SIZE];

void input() {
    cin >> m_value >> k_value;
    for (int i = 0; i < m_value; ++i) {
        ld val;
        cin >> val;
        if (val > TOLERANCE) {
            prob[count] = val;
            idx[count] = i;
            ++count;
        } else {
            answer[i] = 0;
        }
    }
}

void compute() {
    if (k_value >= count) {
        for (int i = 0; i < count; ++i)
            answer[idx[i]] = 1.0;
    } else {
        dp[0] = 1.0;
        for (int mask = 0; mask < (1 << count); ++mask) {
            if (__builtin_popcount(mask) < k_value) {
                ld sum_p = 0.0;
                for (int t = 0; t < count; ++t)
                    if (!((mask >> t) & 1))
                        sum_p += prob[t];
                for (int t = 0; t < count; ++t)
                    if (!((mask >> t) & 1))
                        dp[mask ^ (1 << t)] += prob[t] / sum_p * dp[mask];
            }
        }
        for (int mask = 0; mask < (1 << count); ++mask) {
            if (__builtin_popcount(mask) == k_value) {
                for (int t = 0; t < count; ++t)
                    if ((mask >> t) & 1)
                        answer[idx[t]] += dp[mask];
            }
        }
    }
    for (int i = 0; i < m_value; ++i)
        cout << answer[i] << " ";
    cout << endl;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.precision(10);
    cout << fixed;
    input();
    compute();
    return 0;
}
